ALTER TABLE public.ajustes_club ADD COLUMN cuota_socio numeric DEFAULT NULL;
CREATE OR REPLACE VIEW public.ajustes_club_publicos AS SELECT id,whatsapp_club,nombre_club,temporada_actual,url_clasificacion_futgal,cuota_socio FROM public.ajustes_club;
GRANT SELECT ON public.ajustes_club_publicos TO anon,authenticated;
CREATE TABLE public.pagos (id uuid PRIMARY KEY DEFAULT gen_random_uuid(),socio_id uuid NOT NULL REFERENCES public.socios(id),temporada text NOT NULL,metodo text NOT NULL CHECK (metodo IN ('efectivo','transferencia','bizum','stripe')),importe numeric NOT NULL CHECK (importe>0),fecha_pago date NOT NULL,referencia text,registrado_por uuid,creado_at timestamptz NOT NULL DEFAULT now(),CHECK(metodo<>'stripe' OR referencia IS NOT NULL));
GRANT SELECT ON public.pagos TO authenticated;
GRANT ALL ON public.pagos TO service_role;
ALTER TABLE public.pagos ENABLE ROW LEVEL SECURITY;
CREATE POLICY pagos_lectura ON public.pagos FOR SELECT TO authenticated USING(public.has_club_role('directiva') OR socio_id=public.mi_socio());
CREATE UNIQUE INDEX pagos_stripe_referencia ON public.pagos(referencia) WHERE metodo='stripe';
REVOKE INSERT ON public.socios FROM authenticated;
DROP POLICY IF EXISTS socios_directiva ON public.socios;
CREATE POLICY socios_directiva_lectura ON public.socios FOR SELECT TO authenticated USING(public.has_club_role('directiva'));
CREATE POLICY socios_directiva_editar ON public.socios FOR UPDATE TO authenticated USING(public.has_club_role('directiva')) WITH CHECK(public.has_club_role('directiva'));
REVOKE ALL ON FUNCTION public.alta_socio_email(text,text,text,uuid) FROM PUBLIC,anon,authenticated;
REVOKE ALL ON FUNCTION public.solicitar_alta(text,text,text,boolean,boolean) FROM PUBLIC,anon,authenticated;
COMMENT ON FUNCTION public.alta_socio_email(text,text,text,uuid) IS 'DEPRECATED: replaced by alta_socio_con_pago';
COMMENT ON TABLE public.solicitudes_socios IS 'DEPRECATED: public membership applications retired; no application read or write access';
REVOKE ALL ON public.solicitudes_socios FROM anon,authenticated;
CREATE FUNCTION public.crear_socio_desde_pago(datos jsonb,pago jsonb) RETURNS uuid LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$
DECLARE n uuid; e text:=lower(trim(datos->>'email')); t text; m text:=pago->>'metodo'; amount numeric; d date; ref text:=nullif(trim(pago->>'referencia'),''); u uuid; BEGIN
IF auth.uid() IS NOT NULL THEN IF NOT public.has_club_role('directiva') OR m='stripe' THEN RAISE EXCEPTION 'No autorizado'; END IF; ELSIF current_setting('request.jwt.claim.role',true) IS DISTINCT FROM 'service_role' THEN RAISE EXCEPTION 'Pago no verificado'; END IF;
IF coalesce(length(trim(datos->>'nombre')),0) NOT BETWEEN 1 AND 200 OR e IS NULL OR length(e)>254 OR e !~ '^[^[:space:]@]+@[^[:space:]@]+\.[^[:space:]@]+$' OR coalesce(datos->>'telefono','') !~ '^$|^[0-9]{9,15}$' THEN RAISE EXCEPTION 'Comprueba los datos'; END IF;
IF m IS NULL OR m NOT IN ('efectivo','transferencia','bizum','stripe') THEN RAISE EXCEPTION 'Método no válido'; END IF;
amount:=(pago->>'importe')::numeric; d:=(pago->>'fecha')::date; IF amount IS NULL OR amount<=0 OR amount='NaN'::numeric OR d IS NULL OR d>(now() AT TIME ZONE 'Europe/Madrid')::date THEN RAISE EXCEPTION 'Indica importe y fecha válidos'; END IF;
IF m='stripe' THEN IF ref IS NULL THEN RAISE EXCEPTION 'Referencia obligatoria'; END IF; SELECT socio_id INTO n FROM public.pagos WHERE metodo='stripe' AND referencia=ref; IF n IS NOT NULL THEN RETURN n; END IF; END IF;
SELECT temporada_actual INTO t FROM public.ajustes_club WHERE id=true; PERFORM pg_advisory_xact_lock(hashtextextended(e,0));
SELECT id INTO n FROM public.socios WHERE lower(email)=e ORDER BY fecha_alta LIMIT 1;
SELECT id INTO u FROM auth.users WHERE lower(email)=e AND email_confirmed_at IS NOT NULL LIMIT 1;
IF n IS NULL THEN INSERT INTO public.socios(nombre,email,telefono,estado,temporada,fecha_activacion) VALUES(trim(datos->>'nombre'),e,coalesce(datos->>'telefono',''),'activa',t,now()) RETURNING id INTO n; ELSE UPDATE public.socios SET estado='activa',fecha_baja=NULL,motivo_baja=NULL WHERE id=n; END IF;
INSERT INTO public.usuario_roles(email,rol,socio_id,creado_por,user_id,nombre) VALUES(e,'socia',n,auth.uid(),u,trim(datos->>'nombre')) ON CONFLICT(email,rol,socio_id,patrocinador_id) DO UPDATE SET activo=true;
INSERT INTO public.pagos(socio_id,temporada,metodo,importe,fecha_pago,referencia,registrado_por) VALUES(n,t,m,amount,d,ref,auth.uid()); RETURN n; END $$;
REVOKE ALL ON FUNCTION public.crear_socio_desde_pago(jsonb,jsonb) FROM PUBLIC,anon,authenticated;
GRANT EXECUTE ON FUNCTION public.crear_socio_desde_pago(jsonb,jsonb) TO service_role;
CREATE FUNCTION public.alta_socio_con_pago(p_datos jsonb,p_pago jsonb) RETURNS uuid LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN IF NOT public.has_club_role('directiva') OR p_pago->>'metodo'='stripe' THEN RAISE EXCEPTION 'No autorizado'; END IF; RETURN public.crear_socio_desde_pago(p_datos,p_pago); END $$;
REVOKE ALL ON FUNCTION public.alta_socio_con_pago(jsonb,jsonb) FROM PUBLIC,anon;
GRANT EXECUTE ON FUNCTION public.alta_socio_con_pago(jsonb,jsonb) TO authenticated;
CREATE FUNCTION public.registrar_pago_socio(p_socio uuid,p_pago jsonb) RETURNS uuid LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE n uuid; d date; a numeric; t text; m text:=p_pago->>'metodo'; BEGIN IF NOT public.has_club_role('directiva') THEN RAISE EXCEPTION 'No autorizado'; END IF; d:=(p_pago->>'fecha')::date; a:=(p_pago->>'importe')::numeric; IF m IS NULL OR m NOT IN ('efectivo','transferencia','bizum') OR a IS NULL OR a<=0 OR a='NaN'::numeric OR d IS NULL OR d>(now() AT TIME ZONE 'Europe/Madrid')::date THEN RAISE EXCEPTION 'Pago no válido'; END IF; SELECT temporada_actual INTO t FROM public.ajustes_club WHERE id=true; INSERT INTO public.pagos(socio_id,temporada,metodo,importe,fecha_pago,referencia,registrado_por) VALUES(p_socio,t,m,a,d,nullif(trim(p_pago->>'referencia'),''),auth.uid()) RETURNING id INTO n; RETURN n; END $$;
REVOKE ALL ON FUNCTION public.registrar_pago_socio(uuid,jsonb) FROM PUBLIC,anon;
GRANT EXECUTE ON FUNCTION public.registrar_pago_socio(uuid,jsonb) TO authenticated;
CREATE FUNCTION public.gestion_socios() RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN IF NOT public.has_club_role('directiva') THEN RAISE EXCEPTION 'No autorizado'; END IF; RETURN jsonb_build_object('pagos',(SELECT coalesce(jsonb_agg(to_jsonb(p)),'[]'::jsonb) FROM public.pagos p),'roles',(SELECT coalesce(jsonb_agg(to_jsonb(r)),'[]'::jsonb) FROM public.usuario_roles r WHERE activo),'passwords',(SELECT coalesce(jsonb_object_agg(e.email,coalesce(u.email_confirmed_at IS NOT NULL AND length(u.encrypted_password)>0,false)),'{}'::jsonb) FROM (SELECT DISTINCT lower(email) email FROM public.socios WHERE email IS NOT NULL) e LEFT JOIN auth.users u ON lower(u.email)=e.email)); END $$;
REVOKE ALL ON FUNCTION public.gestion_socios() FROM PUBLIC,anon;
GRANT EXECUTE ON FUNCTION public.gestion_socios() TO authenticated;
CREATE FUNCTION public.personas_club() RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN IF NOT public.is_super_admin() THEN RAISE EXCEPTION 'Solo Super admin'; END IF; RETURN (SELECT coalesce(jsonb_agg(jsonb_build_object('email',e.email,'nombre',e.nombre,'activo',coalesce(u.email_confirmed_at IS NOT NULL AND length(u.encrypted_password)>0,false),'roles',(SELECT coalesce(jsonb_agg(to_jsonb(r)),'[]'::jsonb) FROM public.usuario_roles r WHERE lower(r.email)=e.email AND r.activo))),'[]'::jsonb) FROM (SELECT email,max(nombre) nombre FROM (SELECT lower(email) email,nombre FROM public.usuario_roles UNION ALL SELECT lower(email),nombre FROM public.socios WHERE email IS NOT NULL UNION ALL SELECT lower(email),nombre FROM public.profiles WHERE email IS NOT NULL) x GROUP BY email) e LEFT JOIN auth.users u ON lower(u.email)=e.email); END $$;
REVOKE ALL ON FUNCTION public.personas_club() FROM PUBLIC,anon;
GRANT EXECUTE ON FUNCTION public.personas_club() TO authenticated;
CREATE FUNCTION public.gestionar_rol_persona(p_email text,p_rol public.club_role,p_activo boolean,p_patrocinador uuid DEFAULT NULL,p_motivo text DEFAULT '') RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE e text:=lower(trim(p_email)); n text; r uuid; BEGIN IF NOT public.is_super_admin() OR p_rol NOT IN ('directiva','negocio') THEN RAISE EXCEPTION 'Solo Super admin'; END IF; IF EXISTS(SELECT 1 FROM public.usuario_roles WHERE email=e AND rol='super_admin' AND activo) THEN RAISE EXCEPTION 'No se pueden cambiar estos permisos'; END IF; IF p_activo THEN IF p_rol='directiva' THEN SELECT nombre INTO n FROM public.usuario_roles WHERE email=e LIMIT 1; IF n IS NULL THEN SELECT nombre INTO n FROM public.socios WHERE lower(email)=e LIMIT 1; END IF; PERFORM public.asignar_directiva_email(coalesce(nullif(n,''),e),e); ELSE IF p_patrocinador IS NULL THEN RAISE EXCEPTION 'Elige patrocinador'; END IF; PERFORM public.asignar_negocio_email(p_patrocinador,e); END IF; ELSE IF length(trim(p_motivo))=0 THEN RAISE EXCEPTION 'Indica motivo'; END IF; UPDATE public.usuario_roles SET activo=false WHERE email=e AND rol=p_rol AND activo; INSERT INTO public.registro_permisos(actor_id,afectado_id,accion,motivo) VALUES(auth.uid(),coalesce((SELECT user_id FROM public.usuario_roles WHERE email=e LIMIT 1),auth.uid()),'retirar_'||p_rol::text,p_motivo); END IF; END $$;
REVOKE ALL ON FUNCTION public.gestionar_rol_persona(text,public.club_role,boolean,uuid,text) FROM PUBLIC,anon;
GRANT EXECUTE ON FUNCTION public.gestionar_rol_persona(text,public.club_role,boolean,uuid,text) TO authenticated;